def find_rotation_point(arr):
    """Index of the smallest element in a rotated sorted array."""
    if not arr:
        return -1

    lo, hi = 0, len(arr) - 1

    # If the array is not rotated, the first element is the smallest
    if arr[lo] <= arr[hi]:
        return lo

    while lo < hi:
        mid = (lo + hi) // 2

        # If mid element is greater than the high element, 
        # the rotation point (smallest element) must be to the right of mid.
        if arr[mid] > arr[hi]:
            lo = mid + 1
        else:
            # Otherwise, the rotation point is mid or to the left of mid.
            hi = mid

    return lo
